"use server";

import { revalidatePath } from "next/cache";
import { requireAdmin } from "./auth";
import { db } from "./db";
import { syncDedicatedIpPool, setDedicatedReverse } from "./dedicated-ip";

export async function syncIpPool(): Promise<{ imported?: number; total?: number; error?: string }> {
  await requireAdmin();
  try {
    const r = await syncDedicatedIpPool();
    revalidatePath("/admin/ips");
    return r;
  } catch (e: any) {
    return { error: String(e?.message ?? e).slice(0, 200) };
  }
}

export async function setIpReverse(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  await requireAdmin();
  const address = String(formData.get("address") ?? "");
  const reverse = String(formData.get("reverse") ?? "").trim();
  if (!address || !reverse) return { error: "Address and reverse required." };
  try {
    await setDedicatedReverse(address, reverse.endsWith(".") ? reverse : reverse + ".");
    revalidatePath("/admin/ips");
    return { ok: true };
  } catch (e: any) {
    return { error: String(e?.message ?? e).slice(0, 200) };
  }
}

export async function releaseIpFromServer(ipId: string) {
  await requireAdmin();
  const ip = await db.dedicatedIp.findUnique({ where: { id: ipId } });
  if (!ip) return;
  const { releaseDedicatedIp } = await import("./dedicated-ip");
  if (ip.serverId) await releaseDedicatedIp(ip.serverId);
  revalidatePath("/admin/ips");
}

