/// CUSTOMER: draws from the pool the normal allocate/release flow uses.
/// INTERNAL: Nxeon's own infrastructure (hosting node, cold-email relay, an
/// owner-operated site, ...) — a rare, hand-marked one-off, never assigned by
/// syncDedicatedIpPool()/allocateDedicatedIp().
enum DedicatedIpPurpose {
  CUSTOMER
  INTERNAL
}

/// A public IPv4 (OVH failover/additional IP) that can be assigned to one VM.
/// Synced from the OVH account; each has an OVH Virtual MAC when in use.
model DedicatedIp {
  id           String             @id @default(cuid())
