117	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
118	async function findVirtualMacForIp(address: string): Promise<string | null> {
119	  const macs: string[] = await ovh("GET", `/dedicated/server/${SERVER}/virtualMac`).catch(() => []);
120	  for (const m of macs) {
121	    const ips: string[] = await ovh(
122	      "GET",
123	      `/dedicated/server/${SERVER}/virtualMac/${m}/virtualAddress`
124	    ).catch(() => []);
125	    if (ips.includes(address)) return m;
126	  }
127	  return null;
128	}
