130	/**
131	 * Claim a free IP for a server and create its OVH Virtual MAC so the VM can use it.
132	 * Returns the address + virtualMac + gateway, or null if none available.
133	 */
134	export async function allocateDedicatedIp(
135	  serverId: string,
136	  vmid: number
137	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
138	  if (SANDBOX) {
139	    // Hand out a synthetic dedicated IP without any OVH call or pool mutation.
140	    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
141	  }
142	  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
143	  // server already holds a fully-allocated dedicated IP (ASSIGNED + a bound
144	  // Virtual MAC), return it instead of claiming a second pool IP — re-claiming
145	  // would leak an IP and P2002 on the unique DedicatedIp.serverId.
146	  const mine = await db.dedicatedIp.findUnique({ where: { serverId } });
147	  if (mine && mine.status === "ASSIGNED" && mine.virtualMac) {
148	    return { address: mine.address, virtualMac: mine.virtualMac, gateway: ovhGateway() };
149	  }
150	  if (!ovhConfigured()) return null;
151	  // Atomically claim a FREE ip
152	  const claim = await db.$transaction(async (tx) => {
153	    const ip = await tx.dedicatedIp.findFirst({ where: { status: "FREE" }, orderBy: { createdAt: "asc" } });
154	    if (!ip) return null;
155	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
156	    return ip;
157	  });
158	  if (!claim) return null;
