export async function setIpPurpose(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  await requireAdmin();
  const id = String(formData.get("id") ?? "");
  const purpose = String(formData.get("purpose") ?? "");
  const purposeLabel = String(formData.get("purposeLabel") ?? "").trim();
  if (!id || (purpose !== "CUSTOMER" && purpose !== "INTERNAL")) return { error: "Invalid request." };
  if (purpose === "INTERNAL" && !purposeLabel) return { error: "A label is required for internal IPs." };
  try {
    await db.dedicatedIp.update({
      where: { id },
      // CUSTOMER rows show the assigned Server's hostname, never a purposeLabel —
      // clear it on the way back so a stale internal label can't linger and get
      // displayed if the row is ever re-marked INTERNAL without setting a new one.
      data: { purpose: purpose as "CUSTOMER" | "INTERNAL", purposeLabel: purpose === "INTERNAL" ? purposeLabel : null },
    });
    revalidatePath("/admin/ips");
    return { ok: true };
  } catch (e: any) {
    return { error: String(e?.message ?? e).slice(0, 200) };
  }
}

