/**
 * Inline "mark internal" / "return to customer pool" toggle for one DedicatedIp
 * row. Internal-use IPs (cold-email relay, an owner-operated site, the shared-
 * hosting node) are rare one-off allocations an admin marks by hand — this is
 * the alternative to a raw SQL update the next time one comes up.
 */
export function IpPurposeForm({
  id,
  purpose,
  purposeLabel,
}: {
  id: string;
  purpose: "CUSTOMER" | "INTERNAL";
  purposeLabel: string | null;
}) {
  const [editing, setEditing] = useState(false);
  const [state, action, pending] = useActionState(setIpPurpose, {});

  if (!editing) {
    return (
      <button className="text-xs text-slate-500 hover:text-brand-300" onClick={() => setEditing(true)}>
        Edit
      </button>
    );
  }

  return (
    <form
      action={(fd) => {
        action(fd);
        setEditing(false);
      }}
      className="flex flex-wrap items-center gap-2"
    >
      <input type="hidden" name="id" value={id} />
      <select className="input py-1 text-xs" name="purpose" defaultValue={purpose}>
        <option value="CUSTOMER">Customer</option>
        <option value="INTERNAL">Internal (Nxeon)</option>
      </select>
      <input
        className="input w-56 py-1 text-xs"
        name="purposeLabel"
        placeholder="Label, e.g. Cold Email Relay"
        defaultValue={purposeLabel ?? ""}
      />
      <button className="btn-secondary py-1 text-xs" disabled={pending}>
        Save
      </button>
      <button type="button" className="text-xs text-slate-500 hover:text-slate-300" onClick={() => setEditing(false)}>
        Cancel
      </button>
      {state?.error && <span className="text-xs text-red-400">{state.error}</span>}
    </form>
  );
}

