input.content:
import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { ovhConfigured } from "@/lib/ovh";
import { DEDICATED_IP_PRICE_CENTS } from "@/lib/dedicated-ip";
import type { DedicatedIpPurpose, DedicatedIpStatus } from "@prisma/client";
import { PageHeader, StatCard, Badge, fmtMoney } from "@/components/ui/primitives";
import { SyncIpPoolButton, IpPurposeForm } from "@/components/admin/IpPoolControls";

export const dynamic = "force-dynamic";

const OVH_COST_CENTS = 239;

type IpRow = {
  id: string;
  address: string;
  status: DedicatedIpStatus;
  virtualMac: string | null;
  reverse: string | null;
  purpose: DedicatedIpPurpose;
  purposeLabel: string | null;
  server: { id: string; hostname: string; userId: string } | null;
};

export default async function AdminIps() {
  await requireArea("fleet");
  const ips: IpRow[] = await db.dedicatedIp.findMany({
    include: { server: { select: { id: true, hostname: true, userId: true } } },
    orderBy: { address: "asc" },
  });
  const customerIps = ips.filter((i) => i.purpose === "CUSTOMER");
  const internalIps = ips.filter((i) => i.purpose === "INTERNAL");
  const free = ips.filter((i) => i.status === "FREE").length;
  const assigned = ips.filter((i) => i.status === "ASSIGNED").length;
  const monthlyCost = ips.length * OVH_COST_CENTS;
  // Revenue is per customer-billed IP only. An INTERNAL row (the shared-hosting
  // node, cold-email relay, an owner-operated site) is never charged, so it must
  // not count here even though it's still counted in "Assigned"/"Total IPs"/
  // "OVH cost" above — those track the whole fleet, not just what's billable.
  const billableAssigned = customerIps.filter((i) => i.status === "ASSIGNED").length;
  const monthlyRevenue = billableAssigned * DEDICATED_IP_PRICE_CENTS;

  return (
    <div className="space-y-6">
      <PageHeader title="Dedicated IP pool" sub="Public IPv4 addresses synced from OVH and assigned to customer VMs.">
        {ovhConfigured() && <SyncIpPoolButton />}
      </PageHeader>

      {!ovhConfigured() ? (
        <div className="card border-amber-500/30">
          <Badge tone="amber">OVH not configured</Badge>
          <p className="mt-2 text-sm text-slate-400">
            Add <span className="kbd">OVH_APPLICATION_KEY/SECRET</span> and <span className="kbd">OVH_CONSUMER_KEY</span> to
            <span className="kbd">.env</span> to enable dedicated IPs.
          </p>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
            <StatCard label="Total IPs" value={String(ips.length)} />
            <StatCard label="Assigned" value={String(assigned)} delta={`${free} free`} deltaGood={free > 0} />
            <StatCard label="OVH cost" value={`${fmtMoney(monthlyCost)}/mo`} delta="$2.39/IP" />
            <StatCard label="IP revenue" value={`${fmtMoney(monthlyRevenue)}/mo`} delta={`${fmtMoney(monthlyRevenue - monthlyCost)} margin`} deltaGood={monthlyRevenue >= monthlyCost} />
          </div>

          <div>
            <h2 className="mb-2 text-sm font-medium text-slate-300">Nxeon services ({internalIps.length})</h2>
            <div className="card overflow-x-auto p-0">
              <table className="table-shell">
                <thead>
                  <tr>
                    <th>IP address</th>
                    <th>Status</th>
                    <th>Purpose</th>
                    <th>Virtual MAC</th>
                    <th>Reverse DNS</th>
                    <th />
                  </tr>
                </thead>
                <tbody>
                  {internalIps.length === 0 && (
                    <tr>
                      <td colSpan={6} className="py-6 text-center text-slate-500">
                        No IPs marked internal. Use &quot;Edit&quot; on a row below to mark a one-off allocation
                        (relay, owner-operated site, hosting node) as Nxeon-internal.
                      </td>
                    </tr>
                  )}
                  {internalIps.map((ip) => (
                    <tr key={ip.id}>
                      <td className="font-mono">{ip.address}</td>
                      <td>
                        <Badge tone={ip.status === "FREE" ? "green" : ip.status === "ASSIGNED" ? "brand" : "amber"}>
                          {ip.status.toLowerCase()}
                        </Badge>
                      </td>
                      <td>{ip.purposeLabel ?? <span className="text-slate-500">—</span>}</td>
                      <td className="font-mono text-xs text-slate-400">{ip.virtualMac ?? "—"}</td>
                      <td className="text-xs text-slate-400">{ip.reverse ?? "—"}</td>
                      <td>
                        <IpPurposeForm id={ip.id} purpose={ip.purpose} purposeLabel={ip.purposeLabel} />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div>
            <h2 className="mb-2 text-sm font-medium text-slate-300">Customer-assigned ({customerIps.length})</h2>
            <div className="card overflow-x-auto p-0">
              <table className="table-shell">
                <thead>
                  <tr>
                    <th>IP address</th>
                    <th>Status</th>
                    <th>Assigned to</th>
                    <th>Virtual MAC</th>
                    <th>Reverse DNS</th>
                    <th />
                  </tr>
                </thead>
                <tbody>
                  {customerIps.length === 0 && (
                    <tr>
                      <td colSpan={6} className="py-10 text-center text-slate-500">
                        No dedicated IPs yet. Order Failover IPs in OVH, then click &quot;Sync from OVH&quot;.
                      </td>
                    </tr>
                  )}
                  {customerIps.map((ip) => (
                    <tr key={ip.id}>
                      <td className="font-mono">{ip.address}</td>
                      <td>
                        <Badge tone={ip.status === "FREE" ? "green" : ip.status === "ASSIGNED" ? "brand" : "amber"}>
                          {ip.status.toLowerCase()}
                        </Badge>
                      </td>
                      <td>
                        {ip.server ? (
                          <Link href={`/admin/servers/${ip.server.id}`} className="hover:text-brand-300">
                            {ip.server.hostname}
                          </Link>
                        ) : (
                          <span className="text-slate-500">—</span>
                        )}
                      </td>
                      <td className="font-mono text-xs text-slate-400">{ip.virtualMac ?? "—"}</td>
                      <td className="text-xs text-slate-400">{ip.reverse ?? "—"}</td>
                      <td>
                        <IpPurposeForm id={ip.id} purpose={ip.purpose} purposeLabel={ip.purposeLabel} />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
          <p className="text-xs text-slate-500">
            The worker auto-syncs newly-delivered OVH IPs every 5 minutes. Deleting a server returns its IP to the pool.
          </p>
        </>
      )}
    </div>
  );
}

